<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\StoreProductVariantRequest; use App\Http\Requests\UpdateProductVariantRequest; use App\Models\Product; use App\Models\ProductVariant; use App\Models\Unit; use App\Services\ProductVariantService; use Illuminate\Http\Request; use Inertia\Inertia;
class ProductVariantController extends Controller {public function __construct(private ProductVariantService $service){} public function index(Request $r){$this->authorize('product-variants.view');return Inertia::render('Admin/ProductVariants/Index',['variants'=>$this->service->list($r->only('search','product_id')),'filters'=>$r->only('search','product_id'),'products'=>Product::orderBy('name')->get(['id','name'])]);} public function create(){return $this->form();} private function form(?ProductVariant $variant=null){return Inertia::render('Admin/ProductVariants/Form',['variant'=>$variant?->load('product','unit'),'products'=>Product::orderBy('name')->get(['id','name','sku']),'units'=>Unit::where('status',true)->orderBy('name')->get(['id','name','short_name'])]);} public function store(StoreProductVariantRequest $r){$this->service->create($r->validated());return redirect()->route('admin.product-variants.index')->with('success','Variant created.');} public function edit(ProductVariant $product_variant){return $this->form($product_variant);} public function update(UpdateProductVariantRequest $r,ProductVariant $product_variant){$this->service->update($product_variant,$r->validated());return redirect()->route('admin.product-variants.index')->with('success','Variant updated.');} public function destroy(ProductVariant $product_variant){$this->authorize('product-variants.delete');$this->service->delete($product_variant);return back()->with('success','Variant deleted.');} public function labels(Request $r){$this->authorize('product-variants.print');$ids=$r->validate(['ids'=>['required','array'],'ids.*'=>['integer','exists:product_variants,id']])['ids'];return Inertia::render('Admin/ProductVariants/Labels',['variants'=>ProductVariant::with('product')->whereIn('id',$ids)->get()]);}}
